/** 
 * Requests ads, if they have not already been requested. Must be called on the main thread. <p>Ads will be requested automatically when the player is prepared if this method has not been called, so it is only necessary to call this method if you want to request ads before preparing the player.
 * @param adViewGroup A {@link ViewGroup} on top of the player that will show any ad UI.
 */
public void requestAds(ViewGroup adViewGroup){
  if (hasAdPlaybackState || adsManager != null || pendingAdRequestContext != null) {
    return;
  }
  adDisplayContainer.setAdContainer(adViewGroup);
  AdsRequest request=imaFactory.createAdsRequest();
  try {
    if (adTagUri != null) {
      request.setAdTagUrl(adTagUri.toString());
    } else {
      request.setAdsResponse(castNonNull(adsResponse));
    }
    if (vastLoadTimeoutMs != TIMEOUT_UNSET) {
      request.setVastLoadTimeout(vastLoadTimeoutMs);
    }
    request.setContentProgressProvider(this);
    pendingAdRequestContext=new Object();
    request.setUserRequestContext(pendingAdRequestContext);
    adsLoader.requestAds(request);
  } catch (NullPointerException | IllegalArgumentException e) {
    // Log the exception and handle it gracefully
    Log.e("AdsRequest", "Failed to request ads: " + e.getMessage());
    pendingAdRequestContext = null; // Reset the request context
  }
}
